// Author-time generator for tests/jwt_fixtures.rego: signed lhds-at/1 tokens, each
// differing from `valid` in exactly one respect. A throwaway ES384 key is made per
// run and its PRIVATE half is discarded; only the public JWKS and the tokens are
// written. Signatures are randomised, so this file is NOT regenerated by --check
// (unlike the scope matrix). Re-run only when the contract changes.
// Usage: node tools/gen-jwt-fixtures.mjs
import { generateKeyPairSync, sign } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const out = join(dirname(fileURLToPath(import.meta.url)), '../tests/jwt_fixtures.rego');
export const NOW = 1900000000;
const ISS = 'https://health-cp.example.test';
const FHIR = 'https://visn-01.health.example.test/fhir';
const DICOM = 'https://visn-01.health.example.test/dicomweb';

const mk = () => generateKeyPairSync('ec', { namedCurve: 'P-384' });
const good = mk();
const other = mk();
const b64 = (b) => Buffer.from(b).toString('base64url');
const jwt = (header, claims, key) => {
  const si = `${b64(JSON.stringify(header))}.${b64(JSON.stringify(claims))}`;
  const sig = key ? sign('sha384', Buffer.from(si), { key, dsaEncoding: 'ieee-p1363' }) : Buffer.alloc(0);
  return `${si}.${b64(sig)}`;
};

const hdr = () => ({ alg: 'ES384', typ: 'at+jwt', kid: 'k1' });
const base = () => ({
  iss: ISS, aud: FHIR, jti: 'j-1', lhds_ver: 'lhds-at/1', tenant: 'visn-01',
  sub: 'oid-1', sub_type: 'user', idp_tid: 'tid-1', client_id: 'app-1',
  scope: 'user/Observation.rs', patient: 'p1', lhds_roles: [], lhds_map_ver: 'lhds-scope-map/1',
  pou: ['TREAT'], iat: NOW - 10, exp: NOW + 290,
});

// [name, claimsMutator, headerMutator, signer]
const variants = [
  ['valid', () => {}],
  ['bad_signature', () => {}, () => {}, other.privateKey],
  ['alg_none', () => {}, (h) => { h.alg = 'none'; }, null],
  ['header_alg_es256', () => {}, (h) => { h.alg = 'ES256'; }],
  ['typ_jwt', () => {}, (h) => { h.typ = 'JWT'; }],
  ['iss_entra', (c) => { c.iss = 'https://login.microsoftonline.com/tid-1/v2.0'; }],
  ['ver_2', (c) => { c.lhds_ver = 'lhds-at/2'; }],
  ['act_present', (c) => { c.act = { sub: 'bff' }; }],
  ['cnf_present', (c) => { c.cnf = { jkt: 'x' }; }],
  ['expired', (c) => { c.exp = NOW - 1; c.iat = NOW - 301; }],
  ['iat_future', (c) => { c.iat = NOW + 61; c.exp = NOW + 301; }],
  ['lifetime_301', (c) => { c.iat = NOW - 10; c.exp = NOW + 291; }],
  ['aud_other_base', (c) => { c.aud = DICOM; }],
  ['aud_unknown_base', (c) => { c.aud = 'https://evil.example.test/fhir'; }],
  ['aud_array', (c) => { c.aud = [FHIR]; }],
  ['tenant_off_stamp', (c) => { c.tenant = 'visn-09'; c.aud = 'https://visn-09.health.example.test/fhir'; }],
  ['tenant_uppercase', (c) => { c.tenant = 'Visn-01'; }],
  ['sub_type_service', (c) => { c.sub_type = 'service'; }],
  ['pou_btg', (c) => { c.pou = ['BTG']; }],
  ['user_no_idp_tid', (c) => { delete c.idp_tid; }],
  // scopes
  ['patient_scope_with_patient', (c) => { c.scope = 'patient/Observation.rs'; }],
  ['patient_scope_no_patient', (c) => { c.scope = 'patient/Observation.rs'; delete c.patient; }],
  ['system_scope_on_user_token', (c) => { c.scope = 'system/Observation.rs'; }],
  ['user_scope_on_system_token', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = 'user/Observation.rs'; }],
  ['scope_out_of_order', (c) => { c.scope = 'user/Observation.sr'; }],
  ['scope_unsupported_constraint', (c) => { c.scope = 'user/Observation.rs?code=1234-5'; }],
  ['scope_wildcard_constraint', (c) => { c.scope = 'user/*.rs?category=laboratory'; }],
  ['scope_category_lab', (c) => { c.scope = 'user/Observation.rs?category=laboratory'; }],
  ['scope_wildcard_cruds', (c) => { c.scope = 'user/*.cruds'; }],
  ['scope_empty', (c) => { c.scope = ''; }],
  // roles / operations
  ['system_exporter', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = 'system/*.rs'; c.lhds_roles = ['fhir-data-exporter']; }],
  ['system_no_role', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = 'system/*.rs'; c.lhds_roles = []; }],
  ['system_exporter_no_scope', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = ''; c.lhds_roles = ['fhir-data-exporter']; }],
  ['dicom_reader', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = ''; c.lhds_roles = ['dicom-data-reader']; c.aud = DICOM; }],
  ['dicom_owner', (c) => { c.sub_type = 'system'; delete c.idp_tid; c.scope = ''; c.lhds_roles = ['dicom-data-owner']; c.aud = DICOM; }],
];
// Every required claim, removed once.
for (const k of ['iss', 'aud', 'exp', 'iat', 'jti', 'lhds_ver', 'tenant', 'sub', 'sub_type', 'client_id', 'scope', 'lhds_roles', 'lhds_map_ver', 'pou']) {
  variants.push([`missing_${k}`, (c) => { delete c[k]; }]);
}

const tokens = {};
for (const [name, cm, hm, key] of variants) {
  const c = base(); cm(c);
  const h = hdr(); if (hm) hm(h);
  tokens[name] = jwt(h, c, key === undefined ? good.privateKey : key);
}
const jwk = { ...good.publicKey.export({ format: 'jwk' }), kid: 'k1', alg: 'ES384', use: 'sig' };
const text = [
  '# GENERATED by tools/gen-jwt-fixtures.mjs (signing is randomised; not --check\'d).',
  '# Public JWKS and signed tokens only; the private key was discarded.',
  '# Each token differs from tokens.valid in exactly one respect (see the generator).',
  'package lhds.fixtures',
  '',
  `now := ${NOW}`,
  '',
  `issuer := ${JSON.stringify(ISS)}`,
  '',
  `fhir_base := ${JSON.stringify(FHIR)}`,
  '',
  `dicom_base := ${JSON.stringify(DICOM)}`,
  '',
  `jwks := ${JSON.stringify(JSON.stringify({ keys: [jwk] }))}`,
  '',
  `tokens := ${JSON.stringify(tokens, null, 1)}`,
  '',
].join('\n');
writeFileSync(out, text);
console.log(`wrote ${out}: ${Object.keys(tokens).length} tokens`);
